import type { SidebarButtonProps } from "./SidebarButton.types";
import { Condition } from "../enums";

const base: SidebarButtonProps = {
  id: "testId",
  icon: "down-arrow",
  onClick: () => {},
  title: "Test",
  urlSuffix: "/test",
};

describe("SidebarButton tmp", () => {
  it("renders testid + role", () => {
    const { getByTestId, getByRole } = render(<SidebarButton {...base} />);

    expect(getByTestId("t--sidebar-testId")).toBeInTheDocument();
    expect(getByRole("button")).toBeInTheDocument();
  });

  it("renders condition icon", () => {
    const { getByTestId } = render(
      <SidebarButton {...base} condition={Condition.Warn} />,
    );

    expect(getByTestId("t--sidebar-Warn-condition-icon")).toBeInTheDocument();
  });

  it("calls onClick unless selected", async () => {
    const onClick = jest.fn();
    const { getByRole, rerender } = render(
      <SidebarButton {...base} onClick={onClick} />,
    );

    await userEvent.click(getByRole("button"));
    expect(onClick).toHaveBeenCalledWith("/test");

    onClick.mockClear();
    rerender(<SidebarButton {...base} onClick={onClick} selected />);
    await userEvent.click(getByRole("button"));
    expect(onClick).not.toHaveBeenCalled();
  });
});
